def any_three_distinct_sum_to_zero(arr):
    """
    Returns True if any three distinct elements sum to zero.
    Uses a functional approach with set and any() for O(n^2) time complexity.
    """
    # Convert to list to ensure we can index
    lst = list(arr)
    n = len(lst)

    if n < 3:
        return False

    # Functional approach: use any() with a generator expression
    # For each element at index i, check if any pair (j, k) with j < k and distinct indices sums to -lst[i]
    return any(
        any(
            lst[i] + lst[j] + lst[k] == 0
            for k in range(j + 1, n)
            if lst[j] + lst[k] == -lst[i]
        )
        for j in range(i + 1, n)
        for i in range(n - 2)
    )
