def rescale_to_unit_interval(data):
    """
    Rescale a numeric sequence or numpy array to the [0, 1] range.
    Returns a new list or numpy array of the same type as input.
    If all values are equal, returns zeros of the same shape.
    """
    try:
        import numpy as np
    except ImportError:
        np = None

    if isinstance(data, list):
        arr = data
    elif np is not None and isinstance(data, np.ndarray):
        arr = data
    else:
        # Try to convert to a list of numbers
        arr = list(data)

    # Convert to numpy for convenience if available
    if np is not None:
        a = np.asarray(arr, dtype=float)
        minv = float(np.min(a))
        maxv = float(np.max(a))
        if maxv - minv == 0:
            return np.zeros_like(a)
        return (a - minv) / (maxv - minv)
    else:
        # Fallback pure Python implementation
        minv = min(arr)
        maxv = max(arr)
        if maxv - minv == 0:
            return [0.0 for _ in arr]
        return [(x - minv) / (maxv - minv) for x in arr]


