def count_occurrences(substring: str, string: str) -> int:
    """
    Counts overlapping occurrences of a substring within a string.

    Uses a functional approach with a generator expression and sum.
    Returns 0 if the substring is empty to avoid infinite loops.
    """
    if not substring:
        return 0

    return sum(
        1
        for i in range(len(string) - len(substring) + 1)
        if string[i:i + len(substring)] == substring
    )

