def fibonacci_like(n, cache=None):
    if cache is None:
        cache = {0: 0, 1: 0, 2: 2, 3: 0}
    if n in cache:
        return cache[n]
    result = fibonacci_like(n - 1, cache) + fibonacci_like(n - 2, cache) + fibonacci_like(n - 3, cache) + fibonacci_like(n - 4, cache)
    cache[n] = result
    return result

