def are_numbers_closer_than_threshold(numbers: list[float], threshold: float) -> bool:
    """
    Checks if any two numbers in a list are closer than a given threshold
    by sorting the list and comparing adjacent elements.
    """
    if len(numbers) < 2:
        return False

    sorted_numbers = sorted(numbers)
    return any(
        (sorted_numbers[i] - sorted_numbers[i - 1]) < threshold
        for i in range(1, len(sorted_numbers))
    )

